svg.script:
window.onload = function () {
  const NS = "http://www.w3.org/2000/svg";
  const svg = document.documentElement;

  /*
   * Duplicate d values have been replaced by column-wise medians.
   *
   * Median rows:
   *
   * d = 4:
   *   L1       = 0.0435
   *   Lx       = 0.7495
   *   Lx/L1    = 17.325
   *   Goff     = 0.9475
   *   Goff/L1  = 21.89
   *   Gjit     = 0.993
   *   Gjit/L1  = 22.96
   *   V        = 0.403
   *   V/L1     = 9.30
   *
   * d = 150:
   *   L1       = 6.8185
   *   Lx       = 112.0035
   *   Lx/L1    = 16.45
   *   Goff     = 133.9535
   *   Goff/L1  = 19.75
   *   Gjit     = 66.008
   *   Gjit/L1  = 9.71
   *   V        = 12.666
   *   V/L1     = 1.855
   *
   * d = 200:
   *   L1       = 10.1315
   *   Lx       = 167.056
   *   Lx/L1    = 16.49
   *   Goff     = 183.035
   *   Goff/L1  = 18.065
   *   Gjit     = 87.506
   *   Gjit/L1  = 8.64
   *   V        = 16.6315
   *   V/L1     = 1.645
   *
   * d = 300:
   *   L1       = 16.3415
   *   Lx       = 258.9025
   *   Lx/L1    = 15.85
   *   Goff     = 275.9935
   *   Goff/L1  = 16.905
   *   Gjit     = 134.078
   *   Gjit/L1  = 8.225
   *   V        = 25.1745
   *   V/L1     = 1.55
   *
   * d = 500:
   *   L1       = 27.5715
   *   Lx       = 454.12
   *   Lx/L1    = 16.54
   *   Goff     = 661.195
   *   Goff/L1  = 23.575
   *   Gjit     = 262.06
   *   Gjit/L1  = 9.505
   *   V        = 45.793
   *   V/L1     = 1.66
   */

  const d = [
    2, 3, 4, 6, 8, 10, 20, 35,
    50, 80, 120, 150, 200, 300, 500
  ];

  const absolute = [
    {
      name: "L₁(s)",
      color: "#1f77b4",
      values: [
        0.026, 0.034, 0.0435, 0.078,
        0.101, 0.138, 0.366, 0.724,
        1.349, 2.854, 5.071, 6.8185,
        10.1315, 16.3415, 27.5715
      ]
    },
    {
      name: "Lₓ(s)",
      color: "#ff7f0e",
      values: [
        0.351, 0.535, 0.7495, 1.179,
        1.695, 2.368, 5.907, 12.894,
        22.537, 45.126, 79.941, 112.0035,
        167.056, 258.9025, 454.12
      ]
    },
    {
      name: "Goff(s)",
      color: "#2ca02c",
      values: [
        0.487, 0.722, 0.9475, 1.366,
        2.079, 2.525, 6.018, 13.566,
        23.196, 47.602, 85.891, 133.9535,
        183.035, 275.9935, 661.195
      ]
    },
    {
      name: "Gjit(s)",
      color: "#d62728",
      values: [
        0.683, 0.859, 0.993, 1.424,
        1.845, 2.283, 5.113, 9.645,
        14.834, 27.163, 45.650, 66.008,
        87.506, 134.078, 262.06
      ]
    },
    {
      name: "V(s)",
      color: "#9467bd",
      values: [
        0.236, 0.315, 0.403, 0.514,
        0.676, 0.818, 1.581, 2.831,
        4.192, 7.062, 11.196, 12.666,
        16.6315, 25.1745, 45.793
      ]
    }
  ];

  const normalized = [
    {
      name: "Lₓ/L₁",
      color: "#ff7f0e",
      values: [
        13.56, 15.67, 17.325, 15.14,
        16.73, 17.15, 16.16, 17.81,
        16.70, 15.81, 15.77, 16.45,
        16.49, 15.85, 16.54
      ]
    },
    {
      name: "Goff/L₁",
      color: "#2ca02c",
      values: [
        18.80, 21.13, 21.89, 17.53,
        20.52, 18.29, 16.46, 18.74,
        17.19, 16.68, 16.94, 19.75,
        18.065, 16.905, 23.575
      ]
    },
    {
      name: "Gjit/L₁",
      color: "#d62728",
      values: [
        26.38, 25.14, 22.96, 18.28,
        18.21, 16.54, 13.99, 13.33,
        10.99, 9.52, 9.00, 9.71,
        8.64, 8.225, 9.505
      ]
    },
    {
      name: "V/L₁",
      color: "#9467bd",
      values: [
        9.11, 9.22, 9.30, 6.60,
        6.67, 5.93, 4.32, 3.91,
        3.11, 2.47, 2.21, 1.855,
        1.645, 1.55, 1.66
      ]
    }
  ];

  function el(name, attrs, parent = svg) {
    const element = document.createElementNS(NS, name);

    for (const [key, value] of Object.entries(attrs || {})) {
      element.setAttribute(key, value);
    }

    parent.appendChild(element);
    return element;
  }

  function text(
    content,
    x,
    y,
    className,
    anchor = "middle",
    parent = svg
  ) {
    const element = el(
      "text",
      {
        x: x,
        y: y,
        class: className,
        "text-anchor": anchor
      },
      parent
    );

    element.textContent = content;
    return element;
  }

  function drawPanel(config) {
    const {
      x0,
      y0,
      width,
      height,
      xmin,
      xmax,
      ymax,
      title,
      ylabel,
      xticks,
      yticks,
      series,
      legendRight = false,
      yDecimals = 0
    } = config;

    const right = x0 + width;
    const bottom = y0 + height;

    function X(value) {
      return x0 +
        (
          (Math.log10(value) - Math.log10(xmin)) /
          (Math.log10(xmax) - Math.log10(xmin))
        ) * width;
    }

    function Y(value) {
      return bottom - (value / ymax) * height;
    }

    text(
      title,
      x0 + width / 2,
      35,
      "title"
    );

    // Horizontal gridlines and y-axis labels
    yticks.forEach(value => {
      const y = Y(value);

      el("line", {
        x1: x0,
        y1: y,
        x2: right,
        y2: y,
        class: "grid"
      });

      text(
        value.toFixed(yDecimals),
        x0 - 10,
        y + 4,
        "tick-label",
        "end"
      );
    });

    // Vertical gridlines and x-axis labels
    xticks.forEach(value => {
      const x = X(value);

      el("line", {
        x1: x,
        y1: y0,
        x2: x,
        y2: bottom,
        class: "grid"
      });

      text(
        String(value),
        x,
        bottom + 20,
        "tick-label"
      );
    });

    // Axes
    el("line", {
      x1: x0,
      y1: bottom,
      x2: right,
      y2: bottom,
      class: "axis"
    });

    el("line", {
      x1: x0,
      y1: y0,
      x2: x0,
      y2: bottom,
      class: "axis"
    });

    // Axis labels
    text(
      "Deme Size (d)",
      x0 + width / 2,
      bottom + 48,
      "axis-label"
    );

    const yText = text(
      ylabel,
      x0 - 58,
      y0 + height / 2,
      "axis-label"
    );

    yText.setAttribute(
      "transform",
      `rotate(-90 ${x0 - 58} ${y0 + height / 2})`
    );

    // Legend background
    const legendWidth = legendRight ? 150 : 125;
    const legendX = legendRight
      ? x0 + width - legendWidth - 7
      : x0 + 8;

    el("rect", {
      x: legendX,
      y: y0 + 8,
      width: legendWidth,
      height: series.length * 20 + 15,
      fill: "white",
      opacity: "0.88"
    });

    // Data series and legends
    series.forEach((s, index) => {
      const points = d.map((value, i) => {
        return `${X(value).toFixed(2)},${Y(s.values[i]).toFixed(2)}`;
      }).join(" ");

      el("polyline", {
        points: points,
        class: "series",
        stroke: s.color
      });

      d.forEach((value, i) => {
        el("circle", {
          cx: X(value),
          cy: Y(s.values[i]),
          r: 4,
          fill: s.color,
          class: "point"
        });
      });

      const lx = legendRight
        ? x0 + width - legendWidth + 8
        : x0 + 18;

      const ly = y0 + 20 + index * 20;

      el("line", {
        x1: lx,
        y1: ly - 4,
        x2: lx + 25,
        y2: ly - 4,
        stroke: s.color,
        "stroke-width": 3
      });

      text(
        s.name,
        lx + 32,
        ly,
        "legend",
        "start"
      );
    });
  }

  // Absolute quantities
  drawPanel({
    x0: 80,
    y0: 75,
    width: 450,
    height: 390,
    xmin: 2,
    xmax: 500,
    ymax: 700,
    title: "Time (s) by Deme Size (d)",
    ylabel: "Time (s)",
    xticks: [
      2, 3, 4, 6, 10, 20,
      50, 100, 150, 200, 300, 500
    ],
    yticks: [
      0, 100, 200, 300,
      400, 500, 600, 700
    ],
    yDecimals: 0,
    legendRight: false,
    series: absolute
  });

  // Normalized quantities
  drawPanel({
    x0: 670,
    y0: 75,
    width: 450,
    height: 390,
    xmin: 2,
    xmax: 500,
    ymax: 30,
    title: "Time (L₁ Normalized) by Deme Size (d)",
    ylabel: "Time (L₁ Normalized)",
    xticks: [
      2, 3, 4, 6, 10, 20,
      50, 100, 150, 200, 300, 500
    ],
    yticks: [
      0, 5, 10, 15,
      20, 25, 30
    ],
    yDecimals: 0,
    legendRight: true,
    series: normalized
  });
};
